from 写入第二遍 import add
add('03_003',2,'16:9，青脸与双手的正面近景，白色小体头部在画面左侧，另一只手居右下，拉长部分斜贯中央；轻推近至汗珠与绷紧手指同框。','青抓紧小体的头侧和尾侧，两手反向绷开；中间被拉成细长紧线。她闭眼皱眉，牙齿紧咬，双肘向外撑，手腕继续反拧，汗珠从太阳穴滚落；发力声从齿缝冲出时，两手最后猛拉一寸，紧线达到断开的临界。','双手与长发间露出蓝灰云天，下方一线米灰烟尘。','正上方冷白漫射照亮银白发与珠白小体，指缝和发内压深冷灰。','绷紧的黏韧拉扯声逐渐变尖，衣料因双肩外撑短响。',ja=['ふううっ！！'],tone='闭眼咬牙蓄住一口气，最后一拍向外发力吐出短喝。',kind='mixed',phase='process',node={'青.持物':'双手各握住同一小体一端，反向拉伸'},meaning='青双手抓住小体两处反向拉伸，未断阶段清楚。',characters=['青','白色有尾小体群'],card={'opening':'嫌恶逼成粗暴发力。','beats':['手指扣紧，两肘向外','闭眼皱眉，齿间短喝，最后一寸猛拉'],'coupling':'发声尾拍与双手加力同步，体段绷细。','landing':'受力达到断裂临界，双手仍各自抓牢。'})
add('03_004',1.5,'16:9，稍低机位青的中景，头与两手构成三角，双臂向左右撑开；镜头后撤容纳上方断裂弧线，落幅保留左手头段、右手尾段。','绷细的中段啪地扯断，青双手向外弹开，头段与尾段仍各攥在一手。白色断丝沿她头顶扫成短弧，长马尾晚一拍追过肩侧；她一眼闭紧、一眼眯起，咬住牙，把两腕翻向下方，肩肘随即带着分离部分下砸，镜尾双手冲向腰下。','青轮廓之外铺浅灰白冲击图形底，弧形深灰断丝向两侧甩开，底缘保留一窄带灰绿石铺地面。','云天冷白柔光保持，断开的珠白形体用浅冷灰表现厚度。','一声干脆黏韧断响，双臂下挥带出短风。',kind='action',phase='result',node={'青.持物':'小体已扯为两段，各在一手'},meaning='原格双手分持断段、断丝弧线和咬牙表情保留，随后转入用户确认的用力砸地。',characters=['青','白色有尾小体群'])
add('04_001',4,'16:9，青侧脸近景居画面右侧，空手抬在脸前下方，左后石面落点与反弹白段清晰；稍俯机位固定，把视线方向留到左侧武士画外。','双手的砸落在画面下缘完成，石地上响起一声脆闷接触，白色断段沿左后落点反弹起来。青松开的手指在脸前收拢，另一手退到画外；她猛抬眼望向武士，眉压低，嘴大张着把怒气吐过去。白段落回石面后弹跳幅度缩小，她掌心彻底空下，身体转向对手。','灰绿石铺地面向左后延伸，落点旁有几枚浅灰碎屑，远层淡入米灰烟尘。','上方冷白柔光在脸颊与手背铺开，石面阴影浅而短。','砸地一声黏实闷响接轻小反弹声，发梢扫衣声。',ja=['人をおもちゃ扱いするにも限度があるよ。もう怒るから…！'],tone='先压着怒气责问，句末抬起音量，盯住武士把警告说实。',kind='mixed',phase='result',node={'青.持物':'空手；断段已经砸地','青.目标':'转向鬼头武士'},meaning='用户确认砸地；原格空手、反弹段和朝武士发怒同镜保留。',characters=['青','白色有尾小体群'],card={'opening':'嫌恶通过扯断、砸地释放。','beats':['砸落松手，抬眼转向武士','空手收在脸前，压眉开口警告'],'coupling':'怒句沿抬头与转身推进，地上反弹同时收尾。','landing':'双手空下，注意完整转向武士。'})
